import { Component, EventEmitter, Input, Output } from '@angular/core';
import { CommonModule } from '@angular/common';

// Interface para definir a estrutura do utilizador
export interface UserProfile {
  name: string;
  plan: 'Start' | 'Pro' | 'Black';
  photoUrl?: string | null;
}

@Component({
  selector: 'app-navbar',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './navbar.component.html',
  styleUrls: ['./navbar.component.css']
})
export class NavbarComponent {
  /**
   * Rota ativa para destacar o botão correspondente no menu.
   */
  @Input() activeRoute: string = 'home';

  /**
   * Dados do utilizador logado. Se null, assume estado de visitante.
   */
  @Input() user: UserProfile | null = null;

  /**
   * Emite a nova rota quando um item do menu é clicado.
   */
  @Output() routeChanged = new EventEmitter<string>();

  /**
   * Emite o evento de logout.
   */
  @Output() logout = new EventEmitter<void>();

  // Configuração dos itens do menu central
  menuItems = [
    { label: 'Home', route: 'home' },
    { label: 'Extrato', route: 'statement' },
    { label: 'Pix', route: 'pix' },
    { label: 'Cartões', route: 'cards' },
    { label: 'Investir', route: 'invest' }
  ];

  constructor() {}

  /**
   * Extrai o primeiro nome para exibição na saudação.
   */
  get firstName(): string {
    if (!this.user?.name) return 'Visitante';
    return this.user.name.split(' ')[0];
  }

  /**
   * Gera as iniciais (ex: "Maria Silva" -> "MS") caso não haja foto.
   */
  get userInitials(): string {
    if (!this.user?.name) return 'G';
    const names = this.user.name.trim().split(/\s+/);
    if (names.length === 1) return names[0].substring(0, 2).toUpperCase();
    return (names[0][0] + names[names.length - 1][0]).toUpperCase();
  }

  /**
   * Define as classes CSS dinâmicas para o badge do plano.
   */
  get planClasses(): string {
    const plan = this.user?.plan || 'Start';

    switch (plan) {
      case 'Black':
        return 'bg-slate-900 text-white border-slate-700 shadow-slate-500/20';
      case 'Pro':
        return 'bg-emerald-600 text-white border-emerald-500 shadow-emerald-500/20';
      case 'Start':
      default:
        return 'bg-slate-100 text-slate-500 border-slate-200';
    }
  }

  /**
   * Manipula a navegação e emite o evento para o componente pai.
   */
  navigate(route: string): void {
    this.activeRoute = route;
    this.routeChanged.emit(route);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  /**
   * Aciona o logout.
   */
  onLogout(): void {
    this.logout.emit();
  }
}
